INSERT INTO `settings` (`id`, `title`, `description`, `active`, `user_id`, `created_at`, `updated_at`) VALUES (1,'নির্দেশাবলী','আস্সালামুআলাইকুম,\nবাংলাদেশ কিন্ডারগার্টেন এসোসিয়েশন এর পক্ষ থেকে স্বাগতম। বাংলাদেশ কিন্ডারগার্টেন এসোসিয়েশন এর সফটওয়ার ব্যবহার নির্দেশিকা গুলো ভালোভাবে পড়ে তারপর কাজ করার জন্য বিশেষভাবে অনুরোধ করা হলো। যাতে করে পরবর্তী কাজগুলো করতে সহায়ক হয়।\n\nনির্দেশাবলীঃ\n১. সফটওয়ারটি সুন্দর ও সুচারুরূপে পরিচালনার জন্য Google Chrome ব্যহারের জন্য অনুরোধ করা হলো।\n২. প্রত্যেক সেন্টার অথোরিটির দায়িত্বপ্রাপ্ত ব্যক্তিগণ বাংলাদেশ কিন্ডারগার্টেন এসোসিয়েশন এর অথোরিটি (জনাব মিজানুর রহমান সরকার স্যার) থেকে আপনার সফটওয়ার ব্যবহারের জন্য ইউজার এবং পাসওয়ার্ড সংগ্রহ করে নিজস্ব সংরক্ষিত স্থানে সংরক্ষণ করতে হবে। যা সকল সময় প্রয়োজন হবে।\n৩. প্রত্যেক সেন্টার অথোরিটির দায়িত্বপ্রাপ্ত ব্যক্তিগণ প্রতিটি সেন্টারের আওতাধীন যে সকল স্কুল রেজিষ্ট্রেশন করবেন সে সকল স্কুলগুলোর মেম্বারশীপ নাম্বারসহ এপ্রোভাল পেতে নির্দিষ্ট পরিমান রেজিষ্ট্রেশন ফি প্রদান পূর্বক এসোসিয়েশন এর অথোরিটির (জনাব মিজানুর রহমান সরকার স্যার) সাথে দ্রুত যোগাযোগ করুন।\n৪. রেজিষ্ট্রেশনকৃত স্কুলটি এপ্রোভাল পেয়ে যাওয়ার পর থেকেই Student Registration শুরু করতে পারবেন।\n৫. Student Registration সংক্রান্ত যেকোন ধরনের সমস্যায় উক্ত নাম্বারে (জনাব মশিউর রহমান +880 1518-992461- হোয়াটসঅ্যাপ) যোগাযোগ করুন।\n৬. সফটওয়ার সিকিউরিটি সিষ্টেম ও অনাকাঙ্খিত দূর্ঘটনা এড়াতে ইউজার যদি সর্বোচ্চ ১৫ মিনিট সিষ্টেম ব্যহার না করে থাকেন তাহলে সফটওয়ার এর এক্সেস অটোমেটিক ইনেকটিভ হয়ে যাবে, দয়া করে পুনরায় ব্রাউজার রিফ্রেস/রিলোড করলে ইউজার, পাসওয়ার্ড দিয়ে আবার কাজ করতে পারবেন।\n৭. যে সকল স্কুল পূর্বে রেজিষ্ট্রেশন করেছেন সেগুলোর সকল ইনফরমেশন ফুলফিল করতে হবে।\n৮. সফটওয়ারে ইন্সটিটিউট ও ষ্টুডেন্ট রেজিষ্ট্রেশন করার সময় অবশ্যই ইংরেজীতে টাইপ করতে হবে নতুবা পরবর্তী ষ্টেপগুলোতে সমস্যা হলে এর দায়ভার কর্তৃপক্ষ বহন করবেন না।',1,1,NULL,'2025-09-30 05:31:13');
