INSERT INTO `notices` (`id`, `title`, `description`, `center_id`, `user_id`, `created_at`, `updated_at`) VALUES (21,'ষ্টুডেন্ট রেজিষ্ট্রেশন-২০২৬','আস্সালামুআলাইকুম,\nবাংলাদেশ কিন্ডারগার্টেন অ্যাসোসিয়েশনের আওতাধীন সকল কেন্দ্র প্রধান/কর্তৃপক্ষকে এই মর্মে জানানো যাচ্ছে যে, অদ্য ১.৩০ ঘটিকা হতে আগামীকাল সকাল ৬.০০ ঘটিকা পর্যন্ত  ষ্টুডেন্ট রেজিস্ট্রেশন এবং স্কুল/মেম্বারশীপ রেজিস্ট্রেশন বন্ধ রাখার জন্য বিনীত অনুরোধ করা হচ্ছে। আগামীকাল নির্ধারিত সময়ের পর থেকে যথারীতি  আবার ষ্টুডেন্ট রেজিস্ট্রেশন এবং স্কুল/মেম্বারশীপ রেজিস্ট্রেশন কার্যক্রম শুরু করতে পারবেন ইনশাআল্লাহ।\nধন্যবাদ',0,177,'2026-07-09 00:14:04','2026-08-31 14:27:52');
